package containers

import (
	"fmt"
	"net/netip"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ComposeDocument is the normalized, schema-decoded subset accepted at the
// unprivileged edge. It is never forwarded to a runtime. Unsupported or
// privilege-bearing fields are represented explicitly and rejected.
type ComposeDocument struct{Version string;Services map[string]ComposeService;Volumes map[string]ComposeVolume;Networks map[string]ComposeNetwork;UnknownFields []string}
type ComposeService struct{Image string;Platform string;Command []string;Entrypoint []string;WorkingDirectory string;Environment map[string]string;SecretEnvironment map[string]string;User string;Restart string;Healthcheck ComposeHealthcheck;Volumes []string;Networks []string;Ports []string;DependsOn []string;Privileged bool;PID,IPC,NetworkMode string;Devices,Capabilities,SecurityOptions,Sysctls,ExtraHosts,HostPaths []string;UnknownFields []string}
type ComposeVolume struct{Driver string;External bool;DriverOptions map[string]string}
type ComposeNetwork struct{Internal bool;External bool;Driver string;IPv4,IPv6 string;DriverOptions map[string]string}
type ComposeHealthcheck struct{Kind,Path,PortName string;CommandID ID;IntervalSeconds,TimeoutSeconds int;Retries,StartSuccesses uint8}
type ComposePreview struct{Services []RecipeWorkload;Volumes []RecipeVolume;Networks []RecipeNetwork;Findings []ComposeFinding}
type ComposeFinding struct{Code,Path,Message string;Blocking bool}
type ImageResolver interface{ResolvePinnedImage(registry,repository,tag,platform string)(ImageReference,error)}

func NormalizeCompose(document ComposeDocument,resolver ImageResolver,limits ResourceLimits)(ComposePreview,error){preview:=ComposePreview{};if resolver==nil{return preview,ErrInvalid};for _,field:=range document.UnknownFields{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_UNKNOWN_FIELD",field,"unsupported top-level field",true})};names:=make([]string,0,len(document.Services));for name:=range document.Services{names=append(names,name)};sort.Strings(names);for _,name:=range names{service:=document.Services[name];path:="services."+name;if !idPattern.MatchString(strings.ReplaceAll(name,".","_")){preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_SERVICE_NAME_INVALID",path,"service name is not a safe resource identity",true});continue};for _,field:=range service.UnknownFields{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_UNKNOWN_FIELD",path+"."+field,"unsupported service field",true})};if service.Privileged||service.PID!=""||service.IPC!=""||service.NetworkMode!=""||len(service.Devices)>0||len(service.Capabilities)>0||len(service.Sysctls)>0||len(service.HostPaths)>0{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_PRIVILEGE_FORBIDDEN",path,"host or privilege escape fields are forbidden",true})};for _,option:=range service.SecurityOptions{if option!="no-new-privileges:true"{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_SECURITY_OPTION_FORBIDDEN",path+".security_opt",option,true})}};registry,repository,tag,err:=parseImageName(service.Image);if err!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_IMAGE_INVALID",path+".image",err.Error(),true});continue};image,err:=resolver.ResolvePinnedImage(registry,repository,tag,defaultPlatform(service.Platform));if err!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_IMAGE_UNRESOLVED",path+".image",err.Error(),true});continue};commandID,err:=commandIdentity(name,service.Entrypoint,service.Command);if err!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_COMMAND_INVALID",path+".command",err.Error(),true});continue};spec:=WorkloadSpec{Image:image,CommandID:commandID,Arguments:append(append([]string(nil),service.Entrypoint...),service.Command...),WorkingDirectory:service.WorkingDirectory,User:parseRuntimeUser(service.User),Restart:parseRestart(service.Restart),Update:UpdateManual,Limits:limits,Security:CapabilityPolicy{NoNewPrivileges:true,ReadOnlyRoot:true,DropAllCapabilities:true,SeccompProfile:"runtime/default",MACProfile:"panel/tenant",AllowPublicEgress:true}};if spec.WorkingDirectory==""{spec.WorkingDirectory="/app"};for key,value:=range service.Environment{spec.Environment=append(spec.Environment,EnvironmentValue{Name:key,Value:value})};for key,ref:=range service.SecretEnvironment{spec.Environment=append(spec.Environment,EnvironmentValue{Name:key,SecretRef:ref})};for _,mount:=range service.Volumes{volume,target,readOnly,parseErr:=parseComposeMount(mount);if parseErr!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_MOUNT_INVALID",path+".volumes",parseErr.Error(),true});continue};id,_:=NewID("vol_"+strings.ReplaceAll(volume,".","_"));spec.Volumes=append(spec.Volumes,VolumeMount{VolumeID:id,Target:target,ReadOnly:readOnly})};for _,network:=range service.Networks{id,_:=NewID("net_"+strings.ReplaceAll(network,".","_"));spec.Networks=append(spec.Networks,NetworkAttachment{NetworkID:id,Aliases:[]string{name}})};for index,port:=range service.Ports{parsed,parseErr:=parseComposePort(port,index);if parseErr!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_PORT_INVALID",path+".ports",parseErr.Error(),true});continue};spec.Ports=append(spec.Ports,parsed)};spec.Health=normalizeComposeHealth(service.Healthcheck,spec.Ports);if err:=spec.Validate(TierTenantRootless);err!=nil{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_SERVICE_INVALID",path,err.Error(),true});continue};preview.Services=append(preview.Services,RecipeWorkload{Name:name,Spec:spec,DependsOn:append([]string(nil),service.DependsOn...)})};volumeNames:=make([]string,0,len(document.Volumes));for name:=range document.Volumes{volumeNames=append(volumeNames,name)};sort.Strings(volumeNames);for _,name:=range volumeNames{volume:=document.Volumes[name];if volume.External||volume.Driver!=""&&volume.Driver!="local"||len(volume.DriverOptions)>0{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_VOLUME_DRIVER_FORBIDDEN","volumes."+name,"external and caller-configured volume drivers are forbidden",true});continue};preview.Volumes=append(preview.Volumes,RecipeVolume{Name:name,Class:"managed",MountTarget:"/data",QuotaBytes:limits.StorageBytes,InodeLimit:limits.Inodes,Backup:true})};networkNames:=make([]string,0,len(document.Networks));for name:=range document.Networks{networkNames=append(networkNames,name)};sort.Strings(networkNames);for _,name:=range networkNames{network:=document.Networks[name];if network.External||network.Driver!=""&&network.Driver!="bridge"||len(network.DriverOptions)>0{preview.Findings=append(preview.Findings,ComposeFinding{"COMPOSE_NETWORK_DRIVER_FORBIDDEN","networks."+name,"external and caller-configured network drivers are forbidden",true});continue};preview.Networks=append(preview.Networks,RecipeNetwork{Name:name,Internal:network.Internal})};sort.Slice(preview.Findings,func(i,j int)bool{if preview.Findings[i].Path!=preview.Findings[j].Path{return preview.Findings[i].Path<preview.Findings[j].Path};return preview.Findings[i].Code<preview.Findings[j].Code});for _,finding:=range preview.Findings{if finding.Blocking{return preview,ErrPolicy}};return preview,nil}

func parseImageName(value string)(string,string,string,error){if strings.Contains(value,"@")||strings.ContainsAny(value," \t\r\n"){return "","","",ErrInvalid};tag:="latest";lastSlash:=strings.LastIndex(value,"/");if colon:=strings.LastIndex(value,":");colon>lastSlash{tag=value[colon+1:];value=value[:colon]};parts:=strings.Split(value,"/");registry:="registry-1.docker.io";repository:=value;if len(parts)==1{repository="library/"+value}else if strings.Contains(parts[0],".")||strings.Contains(parts[0],":")||parts[0]=="localhost"{registry=parts[0];repository=strings.Join(parts[1:],"/")};if repository==""||tag==""{return "","","",ErrInvalid};return registry,repository,tag,nil}
func defaultPlatform(value string)string{if value==""{return "linux/amd64"};return value}
func parseRuntimeUser(value string)RuntimeUser{if value==""{return RuntimeUser{UID:1000,GID:1000}};parts:=strings.Split(value,":");uid64,_:=strconv.ParseUint(parts[0],10,32);gid64:=uid64;if len(parts)>1{gid64,_=strconv.ParseUint(parts[1],10,32)};return RuntimeUser{UID:uint32(uid64),GID:uint32(gid64)}}
func parseRestart(value string)RestartPolicy{switch value{case"no","\"\"","''","":return RestartNever;case"on-failure":return RestartOnFailure;default:return RestartUnlessStopped}}
func commandIdentity(name string,entrypoint,command []string)(ID,error){sum:=digestValue(struct{Name string;Entrypoint,Command []string}{name,entrypoint,command});return NewID("cmd_"+sum[:32])}
func parseComposeMount(value string)(string,string,bool,error){parts:=strings.Split(value,":");if len(parts)<2||len(parts)>3||strings.HasPrefix(parts[0],"/"){return "","",false,ErrPolicy};readOnly:=len(parts)==3&&parts[2]=="ro";if len(parts)==3&&!readOnly{return "","",false,ErrPolicy};if !absoluteContainerPath(parts[1]){return "","",false,ErrInvalid};return parts[0],parts[1],readOnly,nil}
func parseComposePort(value string,index int)(Port,error){protocol:=ProtocolTCP;if slash:=strings.LastIndex(value,"/");slash>=0{protocol=PortProtocol(value[slash+1:]);value=value[:slash]};parts:=strings.Split(value,":");raw:=parts[len(parts)-1];parsed,err:=strconv.ParseUint(raw,10,16);if err!=nil||parsed==0||(protocol!=ProtocolTCP&&protocol!=ProtocolUDP){return Port{},ErrInvalid};return Port{Name:fmt.Sprintf("port-%d",index+1),ContainerPort:uint16(parsed),Protocol:protocol},nil}
func normalizeComposeHealth(value ComposeHealthcheck,ports []Port)HealthCheck{health:=HealthCheck{Kind:value.Kind,Path:value.Path,PortName:value.PortName,CommandID:value.CommandID,Interval:time.Duration(value.IntervalSeconds)*time.Second,Timeout:time.Duration(value.TimeoutSeconds)*time.Second,Failures:value.Retries,Successes:value.StartSuccesses};if health.Kind==""{health.Kind="tcp";if len(ports)>0{health.PortName=ports[0].Name};health.Interval=30*time.Second;health.Timeout=5*time.Second;health.Failures=3;health.Successes=1};return health}
var _=netip.Prefix{}
